script:
frappe.ui.form.on("Sales Order", {
          refresh(frm) {
                  frm.toggle_reqd("installation_notes", !!frm.doc.requires_installation);
                  if (frm.doc.docstatus === 1 && frm.doc.requires_installation) {
                          frm.add_custom_button(__("Installation Requests"), () =>
                                  frappe.set_route("List", "Installation Request", { sales_order: frm.doc.name })
                          );
                  }
          },
  });
